1	// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
2	// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
3	package mevwatch
4	
5	import (
6		"fmt"
7		"math"
8	)
9	
10	// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
11	// Command 为字符串命令。
12	type LogEntry struct {
13		Index   int    `json:"index"`
14		Term    int    `json:"term"`
15		Command string `json:"command"`
16	}
17	
18	// InitialState 是跟随者在本次调用开始时的状态。
19	type InitialState struct {
20		// CurrentTerm 是该节点已知的最新任期。
21		CurrentTerm int `json:"currentTerm"`
22		// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
23		CommittedIndex int `json:"committedIndex"`
24		// Log 是从索引 1 开始的连续日志。
25		Log []LogEntry `json:"log"`
26	}
27	
28	// AppendRequest 是顺序到达的一次日志复制请求。
29	type AppendRequest struct {
30		// Term 是领导者任期。
31		Term int `json:"term"`
32		// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
33		// 均为 0 表示日志起点（哨兵），不是真实条目。
34		PrevLogIndex int `json:"prevLogIndex"`
35		PrevLogTerm  int `json:"prevLogTerm"`
36		// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
37		Entries []LogEntry `json:"entries"`
38		// LeaderCommit 是领导者已提交索引。
39		LeaderCommit int `json:"leaderCommit"`
40	}
41	
42	// AppendResult 是单条请求处理后节点对该请求的答复。
43	type AppendResult struct {
44		// Accepted 表示本次复制是否成功。
45		Accepted bool `json:"accepted"`
46		// Reason 是成功 ok 或被拒绝的具体原因。
47		Reason string `json:"reason"`
48		// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
49		Term int `json:"term"`
50		// CommittedIndex 是处理后节点的已提交索引。
51		CommittedIndex int `json:"committedIndex"`
52		// AppliedIndex / ApplyError 仅在启用键值应用（ReplicateOptions.ApplyKV）
53		// 时填充：处理本请求后已应用的最高日志索引与首个应用错误。
54		// 复制是否被接受与命令应用是否失败相互独立表达。
55		AppliedIndex *int        `json:"appliedIndex,omitempty"`
56		ApplyError   *ApplyError `json:"applyError,omitempty"`
57		// applyFields 为 true 时 JSON 输出总是带上 appliedIndex 与 applyError
58		// （无错误时 applyError 为 null）；为 false 时两个字段完全不出现。
59		// 编解码规则见 applyfields.go。
60		applyFields bool
61	}
62	
63	// ReplicateOutput 是整次调用的结果。
64	type ReplicateOutput struct {
65		// Results 与输入请求一一对应。
66		Results []AppendResult `json:"results"`
67		// FinalTerm / FinalCommittedIndex 是最终状态。
68		FinalTerm           int `json:"finalTerm"`
69		FinalCommittedIndex int `json:"finalCommittedIndex"`
70		// FinalLog 是处理完所有请求后的完整日志。
71		FinalLog []LogEntry `json:"finalLog"`
72		// FinalAppliedIndex / FinalKV / FinalApplyError 仅在启用键值应用时填充：
73		// 最终已应用的最高日志索引、最终键值表与首个应用错误。没有请求时同样
74		// 反映初始已提交前缀的应用结果。
75		FinalAppliedIndex *int              `json:"finalAppliedIndex,omitempty"`
76		FinalKV           map[string]string `json:"finalKV,omitempty"`
77		FinalApplyError   *ApplyError       `json:"finalApplyError,omitempty"`
78		// applyFields 含义同 AppendResult.applyFields，编解码规则见 applyfields.go。
79		applyFields bool
80	}
81	
82	// 拒绝原因（稳定标识符，帮助文档中有说明）。
83	const (
84		ReasonOK                      = "ok"
85		ReasonStaleTerm               = "stale term: leader term is lower than current term"
86		ReasonRequestTermNegative     = "invalid request: term is negative"
87		ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
88		ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
89		ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
90		ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
91		ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
92		ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
93		ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
94		ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
95		ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
96		ReasonWouldOverwriteCommitted = "would overwrite committed entry"
97	)
98	
99	type replicateState struct {
100		currentTerm    int
101		committedIndex int
102		log            []LogEntry // log[i].Index == i+1
103	}
104	
105	// ReplicateOptions 控制 Replicate 的可选行为。零值保持原有处理与输出。
106	type ReplicateOptions struct {
107		// ApplyKV 为 true 时把已提交命令解释为键值操作（set/delete），在本次
108		// 调用内从空键值表开始，随提交位置推进按日志次序逐条应用；为 false
109		// 时命令仍是不加解释的任意字符串。
110		ApplyKV bool
111	}
112	
113	// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
114	// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
115	// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
116	func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
117		return ReplicateWithOptions(initial, requests, ReplicateOptions{})
118	}
119	
120	// ReplicateWithOptions 与 Replicate 相同，但可通过 ReplicateOptions 启用
121	// 可选行为（如键值应用）。
122	func ReplicateWithOptions(initial InitialState, requests []AppendRequest, opts ReplicateOptions) (ReplicateOutput, error) {
123		state, err := newReplicateState(initial)
124		if err != nil {
125			return ReplicateOutput{}, err
126		}
127	
128		var applier *kvApplier
129		if opts.ApplyKV {
130			applier = newKVApplier()
131			// 先按索引顺序应用初始日志中已提交的前缀，再顺序处理复制请求。
132			applier.applyUpTo(state.log, state.committedIndex)
133		}
134	
135		results := make([]AppendResult, 0, len(requests))
136		for _, request := range requests {
137			result := state.apply(request)
138			if applier != nil {
139				// 每条请求处理结束后，只应用新提交且尚未应用的日志；应用失败
140				// 不改变复制的接受与否、提交位置或拒绝原因。
141				applier.applyUpTo(state.log, state.committedIndex)
142				result.setApplyFields(applier.appliedIndex, applier.err)
143			}
144			results = append(results, result)
145		}
146		finalLog := append([]LogEntry{}, state.log...)
147		if finalLog == nil {
148			finalLog = []LogEntry{}
149		}
150		output := ReplicateOutput{
151			Results:             results,
152			FinalTerm:           state.currentTerm,
153			FinalCommittedIndex: state.committedIndex,
154			FinalLog:            finalLog,
155		}
156		if applier != nil {
157			output.setApplyFields(applier.appliedIndex, applier.kv, applier.err)
158		}
159		return output, nil
160	}
161	
162	func newReplicateState(initial InitialState) (replicateState, error) {
163		if initial.CurrentTerm < 0 {
164			return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
165		}
166		if initial.CommittedIndex < 0 {
167			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
168		}
169		if initial.CommittedIndex > len(initial.Log) {
170			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
171		}
172		log := append([]LogEntry(nil), initial.Log...)
173		for i, entry := range log {
174			expected := i + 1
175			if entry.Index != expected {
176				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
177			}
178			if entry.Term <= 0 {
179				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
180			}
181			if i > 0 && entry.Term < log[i-1].Term {
182				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
183			}
184			if entry.Term > initial.CurrentTerm {
185				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
186			}
187		}
188		return replicateState{
189			currentTerm:    initial.CurrentTerm,
190			committedIndex: initial.CommittedIndex,
191			log:            log,
192		}, nil
193	}
194	
195	// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
196	func (s *replicateState) termAt(idx int) (term int, ok bool) {
197		switch {
198		case idx == 0:
199			return 0, true
200		case idx < 0 || idx > len(s.log):
201			return 0, false
202		default:
203			return s.log[idx-1].Term, true
204		}
205	}
206	
207	// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
208	// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
209	func (s *replicateState) apply(request AppendRequest) AppendResult {
210		snapshot := *s
211		accepted, reason := s.tryApply(request)
212		if !accepted {
213			// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
214			s.log = snapshot.log
215			s.committedIndex = snapshot.committedIndex
216		}
217		return AppendResult{
218			Accepted:       accepted,
219			Reason:         reason,
220			Term:           s.currentTerm,
221			CommittedIndex: s.committedIndex,
222		}
223	}
224	
225	func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
226		// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
227		// 状态——即使它携带更高任期，也不能更新节点。
228		if reason := validateRequest(request); reason != ReasonOK {
229			return false, reason
230		}
231	
232		// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
233		if request.Term < s.currentTerm {
234			return false, ReasonStaleTerm
235		}
236	
237		// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
238		// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
239		if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
240			return false, ReasonEntryTermDecreases
241		}
242	
243		// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
244		// 任期更新也保留。
245		if request.Term > s.currentTerm {
246			s.currentTerm = request.Term
247		}
248	
249		// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
250		prevTerm, ok := s.termAt(request.PrevLogIndex)
251		if !ok || prevTerm != request.PrevLogTerm {
252			return false, ReasonPrevLogMismatch
253		}
254	
255		// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
256		// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
257		// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
258		// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
259		// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
260		start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
261		cutAt := -1                   // 首个任期不同的现有位置（切片下标）
262		matched := 0
263		for offset, incoming := range request.Entries {
264			idx := start + 1 + offset
265			if idx > len(s.log) {
266				break // 该位置及之后都不存在：稍后整体追加
267			}
268			existing := s.log[idx-1]
269			switch {
270			case existing.Term == incoming.Term && existing.Command == incoming.Command:
271				// 完全相同：保留，重复请求不会产生重复条目。
272				matched++
273			case existing.Term == incoming.Term:
274				// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
275				return false, ReasonCommandConflictSameTerm
276			case idx <= s.committedIndex:
277				// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
278				return false, ReasonWouldOverwriteCommitted
279			default:
280				// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
281				cutAt = idx - 1
282			}
283			if cutAt >= 0 {
284				break
285			}
286		}
287	
288		// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
289		// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
290		if cutAt >= 0 {
291			matched = cutAt - start
292			s.log = append([]LogEntry(nil), s.log[:cutAt]...)
293		}
294		if matched < len(request.Entries) {
295			s.log = append(s.log, request.Entries[matched:]...)
296		}
297	
298		// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
299		// 且不会后退。空条目请求的确认位置就是前一条索引。
300		lastIndex := request.PrevLogIndex + len(request.Entries)
301		newCommit := request.LeaderCommit
302		if lastIndex < newCommit {
303			newCommit = lastIndex
304		}
305		if newCommit > s.committedIndex {
306			s.committedIndex = newCommit
307		}
308		return true, ReasonOK
309	}
310	
311	func validateRequest(request AppendRequest) string {
312		if request.Term < 0 {
313			return ReasonRequestTermNegative
314		}
315		if request.PrevLogIndex < 0 {
316			return ReasonPrevLogIndexNegative
317		}
318		if request.PrevLogTerm < 0 {
319			return ReasonPrevLogTermNegative
320		}
321		if request.LeaderCommit < 0 {
322			return ReasonLeaderCommitNegative
323		}
324		// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
325		// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
326		// tryApply 中单独检查。索引 0 是哨兵，真实条目索引必为正。
327		//
328		// 位置必须用检查过的加法逐条推进：prevLogIndex+1 或链上任一后续位置
329		// 超过当前 int 上限时，输入里的负索引恰好在数学上等于回绕后的位置，
330		// 直接相加会静默溢出把它误判为连续。这种请求属于字段错误，与普通索引
331		// 不连续一样拒绝，不能取得合法请求才有的任期更新效果。空条目不要求
332		// 存在下一位置，最后一条恰好到达 int 上限同样合法。
333		position := request.PrevLogIndex
334		for i, entry := range request.Entries {
335			if position == math.MaxInt {
336				return ReasonEntryIndexGap // 下一位置无法用 int 表示
337			}
338			position++
339			if entry.Index <= 0 || entry.Index != position {
340				return ReasonEntryIndexGap
341			}
342			if entry.Term <= 0 {
343				return ReasonEmptyEntryTerm
344			}
345			if i > 0 && entry.Term < request.Entries[i-1].Term {
346				return ReasonEntryTermDecreases
347			}
348			if entry.Term > request.Term {
349				return ReasonEntryTermExceedsReqTerm
350			}
351		}
352		return ReasonOK
353	}
