770	// TestKVRoundTripFailedReuseKeepsPreviousResult 复用已有结果对象再次读入时，
771	// 类型非法的 JSON 必须明确报错，且原有结果完整保留——即使错误藏在某条请求
772	// 答复内，随后输出也不能混入这次读入的任何部分内容。
773	// TestKVRejectedReplicationKeepsApplyBoundary 回归保障：启用 applyKV 后复制请求
774	// 被拒绝时的状态边界——较高任期或较大 leaderCommit 都不能把未确认的命令写进
775	// 键值表。场景含一个已提交前缀与未提交尾部：
776	//   - 初始任期 2，idx1/idx2 任期均为 2，set balance=100 已提交而 set
777	//     balance=200 未提交：键值表只有 balance=100，应用位置停在 1；
778	//   - 任期 5 的请求把 idx2 任期错称为 3 并要求提交更后位置：因前缀不匹配被拒，
779	//     任期升到 5，但日志、提交位置、应用位置与键值表保持原值，无应用错误；
780	//   - 任期 9 但条目索引不连续的请求属于字段非法：整条拒绝且连任期都不得改变，
781	//     不能与上一种拒绝混为同样的状态变化；
782	//   - 之后任期 5、正确匹配 idx2 的合法请求追加 idx3 并提交到 3：按日志次序
783	//     应用尚未应用的命令，balance=200、receipt=ok，提交与应用位置均为 3。
784	func TestKVRejectedReplicationKeepsApplyBoundary(t *testing.T) {
785		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
786			entry(1, 2, "set balance=100"),
787			entry(2, 2, "set balance=200"), // 未提交尾部：任何拒绝都不能让它被应用
788		}}
789		wantOriginalLog := []LogEntry{
790			entry(1, 2, "set balance=100"),
791			entry(2, 2, "set balance=200"),
792		}
793	
794		// 没有请求时：只应用初始已提交前缀，字符串值原样保留。
795		start := runKV(t, initial)
796		if *start.FinalAppliedIndex != 1 {
797			t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
798		}
799		if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"balance": "100"}) {
800			t.Fatalf("initial kv = %v, want only balance=100", start.FinalKV)
801		}
802		if start.FinalApplyError != nil {
803			t.Fatalf("unexpected initial apply error: %+v", start.FinalApplyError)
804		}
805	
806		// 请求一：高任期 + 前缀任期不匹配 + 更大的 leaderCommit，其余字段全部合法。
807		mismatch := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 3, LeaderCommit: 4,
808			Entries: []LogEntry{entry(3, 5, "set later=x")}}
809		// 请求二：任期 9，但条目索引没有从 prevLogIndex+1 开始——字段非法。
810		gap := AppendRequest{Term: 9, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 5,
811			Entries: []LogEntry{entry(4, 9, "set gap=y")}} // 期望索引 3
812		// 请求三：任期 5、正确匹配 idx2（任期 2）的合法追加。
813		legal := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
814			Entries: []LogEntry{entry(3, 5, "set receipt=ok")}}
815	
816		// 若输入停在第一次拒绝处：任期升到 5，其余一切不动，未确认命令不入表。
817		stopped := runKV(t, initial, mismatch)
818		r := stopped.Results[0]
819		if r.Accepted || r.Reason != ReasonPrevLogMismatch {
820			t.Fatalf("first request should be rejected for prefix mismatch: %+v", r)
821		}
822		if r.Term != 5 {
823			t.Fatalf("higher term should survive rejection: term = %d, want 5", r.Term)
824		}
825		if r.CommittedIndex != 1 {
826			t.Fatalf("commit advanced on rejection: %d, want 1", r.CommittedIndex)
827		}
828		if got := appliedIndexOf(t, r); got != 1 {
829			t.Fatalf("applied index advanced on rejection: %d, want 1", got)
830		}
831		if r.ApplyError != nil {
832			t.Fatalf("rejection must not produce an apply error: %+v", r.ApplyError)
833		}
834		if stopped.FinalTerm != 5 || stopped.FinalCommittedIndex != 1 {
835			t.Fatalf("final state after stop: term=%d ci=%d, want 5/1",
836				stopped.FinalTerm, stopped.FinalCommittedIndex)
837		}
838		if !reflect.DeepEqual(stopped.FinalLog, wantOriginalLog) {
839			t.Fatalf("log changed after rejection: %+v", stopped.FinalLog)
840		}
841		if *stopped.FinalAppliedIndex != 1 {
842			t.Fatalf("final appliedIndex = %d, want 1", *stopped.FinalAppliedIndex)
843		}
844		if !reflect.DeepEqual(finalKVOf(t, stopped), map[string]string{"balance": "100"}) {
845			t.Fatalf("kv changed after rejection: %v, want only balance=100", stopped.FinalKV)
846		}
847		if stopped.FinalApplyError != nil {
848			t.Fatalf("unexpected final apply error: %+v", stopped.FinalApplyError)
849		}
850	
851		// 完整过程：两种拒绝之后合法请求仍能追加并提交。
852		out := runKV(t, initial, mismatch, gap, legal)
853		wantResults := []struct {
854			accepted bool
855			reason   string
856			term     int
857			commit   int
858			applied  int
859		}{
860			{false, ReasonPrevLogMismatch, 5, 1, 1}, // 任期更新保留，其余不动
861			{false, ReasonEntryIndexGap, 5, 1, 1},   // 字段非法：连任期都停在 5
862			{true, ReasonOK, 5, 3, 3},               // 追加 idx3，提交并应用到 3
863		}
864		if len(out.Results) != len(wantResults) {
865			t.Fatalf("got %d results, want %d", len(out.Results), len(wantResults))
866		}
867		for i, want := range wantResults {
868			got := out.Results[i]
869			if got.Accepted != want.accepted || got.Reason != want.reason {
870				t.Fatalf("result %d = accepted=%v reason=%q, want accepted=%v reason=%q",
871					i, got.Accepted, got.Reason, want.accepted, want.reason)
872			}
873			if got.Term != want.term || got.CommittedIndex != want.commit {
874				t.Fatalf("result %d state = term %d ci %d, want term %d ci %d",
875					i, got.Term, got.CommittedIndex, want.term, want.commit)
876			}
877			if applied := appliedIndexOf(t, got); applied != want.applied {
878				t.Fatalf("result %d appliedIndex = %d, want %d", i, applied, want.applied)
879			}
880			if got.ApplyError != nil {
881				t.Fatalf("result %d unexpected apply error: %+v", i, got.ApplyError)
882			}
883		}
884	
885		// 最终状态：任期 5、提交 3；日志为原两条加 idx3，未提交尾部命令原样保留。
886		wantLog := []LogEntry{
887			entry(1, 2, "set balance=100"),
888			entry(2, 2, "set balance=200"),
889			entry(3, 5, "set receipt=ok"),
890		}
891		if out.FinalTerm != 5 || out.FinalCommittedIndex != 3 {
892			t.Fatalf("final replication state = term %d ci %d, want term 5 ci 3",
893				out.FinalTerm, out.FinalCommittedIndex)
894		}
895		if !reflect.DeepEqual(out.FinalLog, wantLog) {
896			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
897		}
898		if *out.FinalAppliedIndex != 3 {
899			t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
900		}
901		// 按原日志顺序应用：idx2 把 balance 改成 200，idx3 写入 receipt。
902		wantKV := map[string]string{"balance": "200", "receipt": "ok"}
903		if !reflect.DeepEqual(finalKVOf(t, out), wantKV) {
904			t.Fatalf("final kv = %v, want %v", out.FinalKV, wantKV)
905		}
906		if out.FinalApplyError != nil {
907			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
908		}
909	}
