923	// TestKVTermConflictReplacesUncommittedSuffix 回归保障：新条目在 idx2 处与旧
924	// 日志任期冲突（旧任期 2、新任期 3）后，idx2 及其后的未提交旧后缀被整段替换；
925	// 替换区间内的新条目（idx3 任期 4）即使与旧位置同任期、命令不同，也不再逐位
926	// 比对，复制照常成功。已提交前缀 idx1 完整保留，原 idx4 被删除，最终日志只剩
927	// 三条。开启 applyKV 时提交与应用位置都推进到 3：键值表只反映新日志的命令
928	// （balance=300、receipt=ok），旧后缀中的 delete balance 与 set legacy=old
929	// 不得留下任何效果，也没有应用错误。
930	func TestKVTermConflictReplacesUncommittedSuffix(t *testing.T) {
931		out := runKV(t, uncommittedSuffixInitial(),
932			AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
933				Entries: []LogEntry{
934					entry(2, 3, "set balance=300"),
935					entry(3, 4, "set receipt=ok"), // 与旧 idx3 同任期不同命令：位于被替换后缀内，允许
936				}},
937		)
938	
939		if len(out.Results) != 1 {
940			t.Fatalf("got %d results, want 1", len(out.Results))
941		}
942		result := out.Results[0]
943		if !result.Accepted || result.Reason != ReasonOK {
