package main

import (
	"encoding/json"
	"fmt"
	"testing"

	"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
)

func TestCaseVariant(t *testing.T) {
	// 单条答复，只有 ApplyError: null，字段名首字母大写
	data := `{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"ApplyError":null}`
	var r mevwatch.AppendResult
	if err := json.Unmarshal([]byte(data), &r); err != nil {
		t.Fatal(err)
	}
	out, _ := json.Marshal(r)
	fmt.Println("AppendResult:", string(out))

	// 整次结果，finalKV 换成 FINALKV
	data2 := `{"results":[],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[],"FINALKV":{"a":"1"}}`
	var o mevwatch.ReplicateOutput
	if err := json.Unmarshal([]byte(data2), &o); err != nil {
		t.Fatal(err)
	}
	out2, _ := json.Marshal(o)
	fmt.Println("ReplicateOutput:", string(out2))

	// 相似无关字段不应触发
	data3 := `{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"myAppliedIndex":9}`
	var r2 mevwatch.AppendResult
	if err := json.Unmarshal([]byte(data3), &r2); err != nil {
		t.Fatal(err)
	}
	out3, _ := json.Marshal(r2)
	fmt.Println("SimilarKey:", string(out3))
}
EOF
